def parse(data, raw=False, quiet=False):
    """
    Main text parsing function

    Parameters:

        data:        (string)  text data to parse
        raw:         (boolean) unprocessed output if True
        quiet:       (boolean) suppress warning messages if True

    Returns:

        List of Json objects if data is processed and Raw data if raw = true.
    """
    jc.utils.compatibility(__name__, info.compatible, quiet)
    jc.utils.input_type_check(data)

    structure = {}
    items = []
    lines = data.splitlines()
    index = 0
    place = 0
    inc = 0

    if not jc.utils.has_data(data):
        return items

    for line in lines:
        temp = line.split()
        for word in temp:
            if word == 'via':
                y = {'via': temp[place + 1]}
                place += 1
                structure.update(y)
            elif word == 'dev':
                y = {'dev': temp[place + 1]}
                place += 1
                structure.update(y)
            elif word == 'metric':
                if raw:
                    y = {'metric': temp[place + 1]}
                else:
                    y = {'metric': jc.utils.convert_to_int(temp[place+1])}
                place += 1
                structure.update(y)
            elif word == 'proto':
                y = {'proto': temp[place + 1]}
                place += 1
                structure.update(y)
            elif word == 'scope':
                y = {'scope': temp[place + 1]}
                place += 1
                structure.update(y)
            elif word == 'src':
                y = {'src': temp[place + 1]}
                place += 1
                structure.update(y)
            elif word == 'status':
                y = {'status': temp[place + 1]}
                place += 1
                structure.update(y)
            elif word == 'default':
                y = {'ip': 'default'}
                place += 1
                structure.update(y)
            elif word == 'linkdown':
                y = {'status': 'linkdown'}
                place += 1
                structure.update(y)
            else:
                y = {'ip': temp[0]}
                place += 1
                structure.update(y)
        if y.get("ip") != "":
            items.append(structure)
        structure = {}
        place = 0
        index += 1
        inc += 1

    return items

