    body = _remove_ansi_c(body)
    body = _remove_bookends(body)
    body_split = shlex.split(body)
    values: Dict = {}
    for item in body_split:
        key, val = item.split('=', maxsplit=1)
        key = _remove_bookends(key, '[', ']')
